+pub(super) fn peel_expr<'a, 'b>(mut expr: &'b Expression<'a>) -> &'b Expression<'a> {
+    loop {
+        expr = match wrapper(expr) {
+            Some(Wrapper::Transparent(inner) | Wrapper::Asserted(inner, _)) => inner,
+            Some(Wrapper::Instantiation(_)) | None => return expr,
